  // --- PC-56 TENANT-1b-2 · W154 tenant-scoped member suspension ---
  'member.suspendScope': 'આ ફક્ત તમારી સંસ્થા પર લાગુ પડે છે. સભ્યનું ખાતું ચાલુ રહે છે, અને જો તેઓ બીજી સંસ્થાના પણ સભ્ય હોય કે સ્ટોરફ્રન્ટ વાપરે, તો તેના પર કોઈ અસર થતી નથી. આખા પ્લેટફોર્મ પરની સ્થગિતતા કોઈ સંસ્થા કરી શકતી નથી.',
  'member.suspendEffect.signIn': 'તેઓ તમારી સંસ્થામાં લૉગિન કરી શકશે નહીં. જે પહેલેથી લૉગિન છે તેમની પહોંચ 15 મિનિટમાં બંધ થાય છે.',
  'member.suspendEffect.permissions': 'સ્થગિતતા દરમિયાન અહીં તેમની પાસે કોઈ પરવાનગી રહેતી નથી.',
  'member.suspendEffect.listingNew': 'તેઓ કોઈ લિસ્ટિંગ બનાવી, પ્રકાશિત કે ફરી પોસ્ટ કરી શકતા નથી — તરત જ.',
  'member.suspendEffect.listingLive': 'તેમની ચાલુ લિસ્ટિંગ બજાર, વેચનારની પ્રોફાઈલની ગણતરી અને ભાવપટ્ટીમાંથી હટી જાય છે — તરત જ.',
  'member.suspendEffect.ownSight': 'તેઓ પોતાની લિસ્ટિંગ જોઈ શકે છે, જેથી તેમને એપ બગડેલી ન લાગે.',
  'member.suspendEffect.payouts': 'તમારા પર બાકી નાણાં તો ચૂકવાય જ છે. સ્થગિતતા ક્યારેય જપ્ત કરતી નથી.',
  'member.suspendEffect.orders': 'ચાલુ ઓર્ડર ચાલુ રહે છે — ખરીદનારે પૈસા ભર્યા છે અને તેનો માલ બને છે.',
  'member.suspendEffect.notice': 'હાલ સભ્યને આપમેળે કોઈ જાણ થતી નથી. કૃપા કરીને તેમને ફોન કરો.',
  'member.suspendSelf': 'તમે તમારું પોતાનું સભ્યપદ સ્થગિત કરી શકતા નથી. સભ્ય-ડેસ્કની પહોંચ ધરાવતા સાથીને કહો.',
