  'member.ok.suspended': 'તમારી સંસ્થામાં સ્થગિત અને નોંધાયું. તેમની લિસ્ટિંગ બજારમાંથી હટી ગઈ છે.',
  'member.ok.alreadySuspended': 'આ સભ્ય પહેલેથી સ્થગિત હતા, તેથી કંઈ બદલાયું નથી અને તમારું નવું કારણ નોંધાયું નથી. મૂળ કારણ નીચે દેખાડ્યું છે.',
