  'import.subtitle': 'વ્યક્તિ દીઠ એક પંક્તિ. કંઈ પણ બનાવ્યા પહેલાં દરેક પંક્તિ ચકાસાય છે, અને કોઈ બે વાર ઉમેરાતું નથી — સભ્યો ફોન નંબરથી મેળવાય છે.',
  'import.back': 'સભ્યો પર પાછા',
  'import.consent': 'તમે જેમને આયાત કરો છો તે બધાને સંદેશ જાય છે કે કોણે ઉમેર્યા, કઈ સંસ્થા, અને કેમ — તેમની જ ભાષામાં. કૃપા કરીને ખાતરી કરો કે તે વાક્ય તમને તેમને વંચાવવામાં સહજ લાગે.',
