  'dsp.gateNoAmount': 'આ વિવાદમાં કોઈ વિવાદિત રકમ નોંધાઈ નથી, તેથી મંજૂરી આપવા આંકડો નથી. સ્પષ્ટ રકમ સાથે ઉકેલો; નિયમ એ આંકડા પર લાગુ થશે.',
  'dsp.gateUnreadable': 'મંજૂરીની સ્થિતિ વાંચી શકાઈ નહીં. આ પાનાંથી કંઈ પ્રસ્તાવિત કે મંજૂર થયું નથી.',
  'dsp.gate.singleSignature': '{amount} નું રિફંડ તમારી સંસ્થાની {threshold} મર્યાદાથી નીચે છે, તેથી order.refund ધરાવતી એક વ્યક્તિ તે ચલાવી શકે.',
  'dsp.gate.needsProposal': '{amount} નું રિફંડ તમારી {threshold} મર્યાદા પર કે ઉપર છે. અહીં પ્રસ્તાવ મૂકો; order.refund ધરાવતો બીજો સાથી સહી કરે પછી જ પૈસા હલશે.',
  'dsp.gate.awaitingChecker': '{amount} નું રિફંડ પ્રસ્તાવિત છે અને બીજી વ્યક્તિની સહીની રાહમાં છે.',
  'dsp.gate.rejectedByChecker': 'ચકાસનારે આ રિફંડ નકાર્યું. કારણ નીચે છે; કેસ બદલાયો હોય તો નવો આંકડો પ્રસ્તાવો.',
  'dsp.gate.ready': 'એક સાથીએ {amount} માટે સહી કરી છે. એ જ આંકડા સાથે ઉકેલતાં રિફંડ ચાલશે અને મંજૂરી વપરાઈ જશે.',
  'dsp.gate.amountChanged': 'સહી થયેલી રકમ અને હાલ આપાતી રકમ અલગ છે. સહી આંકડા માટે હોય, કેસ માટે નહીં — નવી રકમ પ્રસ્તાવો.',
  'dsp.gate.alreadyApplied': 'આ કેસમાં રિફંડ પહેલેથી લાગુ થઈ ગયું છે. બીજું બમણું રિફંડ થશે.',
  'dsp.gate.unknown': 'મંજૂરીની સ્થિતિ ઓળખાઈ નહીં, તેથી અહીં કોઈ કાર્ય આપ્યું નથી.',
  'dsp.thresholdDefault': 'તમારી સંસ્થાએ મર્યાદા નક્કી કરી નથી, તેથી પ્લેટફોર્મનું ડિફોલ્ટ લાગુ છે.',
