  'inv.kpiCountNote': 'ઓર્ડર કન્ફર્મ થતાં જ સ્વયં બને છે — હાથે કંઈ કરવાનું નથી.',
  'inv.kpiTaxable': 'કરપાત્ર મૂલ્ય',
  'inv.kpiTaxableNote': 'મોટા ભાગની ઉપજ GST-મુક્ત છે, તેથી આ મુખ્યત્વે ફી અને પ્રોસેસ્ડ માલ છે.',
  'inv.kpiTax': 'આ ઇનવોઇસનો GST',
  'inv.kpiTaxNote': 'વસૂલ થયેલી રકમમાંથી કાઢેલો; તે પ્લેટફોર્મના gst_payable ખાતામાં જાય છે.',
  'inv.withoutBreakdown': 'આ માસના {n} ઇનવોઇસ તેમનું ટેક્સ-વિભાજન નોંધાયા પહેલાં જારી થયા હતા. તે ઉપરના આંકડામાં સમાવ્યા નથી અને ફરી કાઢી શકાતા નથી — ખરીદદારની નકલમાં એ જ આંકડો છે જેની સાથે તે જારી થયા.',
  'inv.incompleteBasis': '{n} ઇનવોઇસમાં એવી પંક્તિ છે જેની ટેક્સ દર નોંધાઈ નથી. તે ખરીદદાર માટે માન્ય છે, પણ GSTR-1 નિકાસ તેમને છોડી દે છે — નોંધ્યા વગરની દરે ફાઇલ કરવા કરતાં સારું.',
