  'chg.noCommodityRates': 'કોઈ શ્રેણી માટે વસ્તુ-વિશેષ GST દર નોંધાયેલ નથી. તેથી વેપાર બિલોની માલ પંક્તિ પર “દર નોંધાઈ નથી” દેખાય છે અને તે GSTR-1 નિકાસમાંથી બહાર રહે છે: પ્લેટફોર્મ ઉપજની દરનું અનુમાન કરશે નહીં. તમે જે શ્રેણીઓમાં વેચો છો તેની દરો નોંધાવવા પ્લેટફોર્મ કમ્પ્લાયન્સને કહો.',
