  'wal.exportCsv': 'CSV kadho',
  'wal.exportReady': 'Export taiyar: {rows} entries, receipt sathe jema row ganatri, data no sha256 ane kone maangyu te nondhayel chhe.',
  'wal.exportBlocked.noPermission': 'Export mate wallet.org_view paravangi joie.',
  'wal.exportBlocked.windowTooWide': 'Export pehla tarikh range nani karo — export 366 divas sudhi maryadit chhe.',
  'wal.exportBlocked.nothingToExport': 'Aa gala ma kadhva jevu kai nathi.',
  'wal.err.exportTooLarge': 'Aa gala ma ek file thi vadhare entries chhe. Tarikh range nani karo — vachche mahine atki jato statement pooro samjhay chhe.',
  'wal.err.exportFailed': 'Export banavi shakayu nahi. Kai nondhayu nathi ane kai badlayu nathi.',
  'wal.err.windowTooWide': 'Tarikho 366 divas ke tethi ochhi sahi range hovi joie.',
  'wal.colWhen': 'Kyare',
  'wal.colTxn': 'Vyavahar',
  'wal.colType': 'Prakar',
