  'wal.colBalanceAfter': 'Pachi no balance (te khata no)',
  'wal.noEditByDesign': 'Aa screen par edit no control jaani-joine nathi. Bhool reversal entry thi sudharay chhe, tethi itihas aakhi vaat kahe chhe — ane database update ni na kahe chhe bhale koi screen maange.',
  'wal.keysetOnly': 'Page aagal-pachhal chale chhe, number thi nahi: append-only ledger par page number kale bijej dekhadse.',

  // PC-56 TENANT-4b · W145/W146 — the organisation's payout queue and the batch approval gate.
  'po.title': 'Payout',
  'po.intro': 'Tamara sabhyo ane shramiko ne paisa. Order pura thay ane cycle band thay tyare payout aapmele line ma aave chhe; te ek batch ma jaay chhe jena par biji vyakti e sahi kari hoy.',
  'po.makerCheckerNote': 'Ek vyakti aaj raat no batch taiyar kare chhe, biji vyakti teni manjuri aape chhe. Aa wave pehla e sahi kyay nahoti — ek scheduled job jate paisa mokalto hato.',
