  'dairy.centres.move.datesNote': "ખાલી રાખો તો ફેરફાર આજથી અમલી થશે. જે દિવસે કે તે પહેલાં આ સભ્યે પોતાના વર્તમાન કેન્દ્ર પર દૂધ આપ્યું છે, તે તારીખથી અમલી થઈ શકતું નથી — છપાયેલી પરચી કહે છે તેઓ ક્યાં ઊભા હતા, અને રેકોર્ડે તેની સાથે મેળ ખાવો જોઈએ.",
