  'dairy.centres.move.refusal.MEMBERSHIP_INACTIVE': "આ સભ્યપદ પૂરું થયું છે. ફરી જોડાવું નવું નામાંકન છે, બદલી નહીં — નહીંતર કોઈ કાર્ડ નવા કાઉન્ટર પર કોઈના નિર્ણય વગર જીવતું થઈ જાય.",
