  'dairy.bmc.alerting.noSilenceRule': "સેન્સરની ચુપકીદી પર નજર રાખતો કોઈ નિયમ નથી, તેથી આ સ્ક્રીન ગૅપ બતાવે છે અને કોઈને કૉલ જતો નથી. બદલવા માટે silent-device નિયમ ઉમેરો.",
  'dairy.bmc.alerting.silenceRuleDiffers': "જે નિયમ કોઈને બોલાવે છે તેની મર્યાદા આ સ્ક્રીનના ગૅપથી અલગ છે — બંને વાજબી છે, પણ ફોન એક જ વગાડે છે.",
  'dairy.bmc.alerting.silenceUnderCadence': "ચુપકીદીનો નિયમ મૂલ્યાંકનની અવધિ કરતાં પણ કડક છે, તેથી કૉલ બરાબર સમયે નહીં, પછીની તપાસ વખતે જાય છે.",
  'dairy.bmc.alerting.silenceRuleAt': "આટલી મિનિટની ચુપકીદી પછી કોઈને કૉલ જાય છે:",
  'dairy.bmc.alerting.checkedEvery': "તપાસ દર (મિનિટ):",
  'dairy.bmc.alerting.criticalNotCatalogued': "આ ડિપ્લોયમેન્ટ પર ગંભીર અલર્ટ કોઈને જગાડી શકતું નથી: ગંભીર અલર્ટની ઘટના સૂચિબદ્ધ નથી, તેથી શાંત કલાકોમાં સવાર સુધી દરેક ફોન ચૅનલ ચૂપ રહે છે.",
  'dairy.bmc.alerting.criticalNoVoice': "આ ડિપ્લોયમેન્ટ પર ગંભીર અલર્ટના વૉઇસ ચૅનલ માટે કોઈ સંદેશ નથી, તેથી ઑપરેટરને ટેક્સ્ટ અને પુશ મળે છે, કૉલ નહીં.",

