  // ---- PC-56 TENANT-6e-1 · W172 (Dairy insights) ----
  'dairy.insights.title': "ડેરી અંતર્દૃષ્ટિ",
  'dairy.insights.lead': "છેલ્લા નેવું દિવસમાં તમારી સહકારીના પોતાના રેકોર્ડ શું કહે છે — અને જ્યાં આ પ્લૅટફૉર્મ કંઈ જાણી જ શકતું નથી, ત્યાં જવાબ જેવો દેખાતો આંકડો નહીં, પણ શું ખૂટે છે એ.",
