  'courses.gateNote.THUMBNAILS_REAL': "ફ્રેમ પાઠના પોતાના વિડિયોમાં જાહેર કરેલી સેકન્ડ છે; આ પ્લેટફોર્મ સમય સંગ્રહે છે, છબી બનાવતું નથી (ફ્રેમ કાઢવાનું સાધન નથી).",
  'courses.quiz.thresholdOnLesson': "પ્રમાણપત્ર થ્રેશોલ્ડ દરેક ક્વિઝ પાઠ પર જાહેર થાય છે (W413) અને ફક્ત પ્રમાણપત્રને રોકે છે — આગળનો પાઠ કદી નહીં.",
