  'lessons.outlineTitle': "કોર્સ બિલ્ડર — રૂપરેખા",
  'lessons.outlineSub': "કોર્સ જીવનચક્ર: draft | review | published | archived. રૂપરેખા દરેક વિડિયોને તેના ફક્ત-ઑડિયો જોડિયા સાથે જોડે છે; નિયમ ડિફૉલ્ટ છે, પસંદગી નહીં.",
  'lessons.outlineCaption': "પાઠ સંગ્રહિત ક્રમમાં. ઉપર/નીચે ખસેડવું કારણ સાથેની ક્રિયાઓ છે.",
  'lessons.outlineQuote': "“કોર્સ એ પાઠોમાં વહેંચાયેલું વચન છે”",
  'lessons.addLesson': "પાઠ ઉમેરો",
  'lessons.rule.title': "નિયમ.",
  'lessons.rule.body': "દરેક વિડિયો પાઠનું ફક્ત-ઑડિયો જોડિયું હોવું જ જોઈએ — 2G ફૉલબેક. ઑડિયોને પોતાના પાઠ તરીકે અપલોડ કરો અને વિડિયોના ફોર્મ પર જોડો.",
  'lessons.state.readOnly': "ફક્ત-વાંચવાની રૂપરેખા — આ કોર્સ બીજા પ્રશિક્ષકનો છે. તમે રૂપરેખા જોઈ શકો, બદલી નહીં શકો.",
  'lessons.state.notEnabled': "કોર્સ બિલ્ડર બંધ — આ મોડ્યુલ આ ટેનન્ટ/પ્લાન માટે બંધ છે. કંઈ તૂટ્યું નથી; તે સક્ષમ નથી.",
  'lessons.state.notEnabledHint': "પ્લાન સેટિંગ જુઓ.",
  'lessons.state.restricted': "સંપાદન પ્રતિબંધિત — અપલોડ માટે આ કોર્સ પર પ્રશિક્ષક ભૂમિકા જોઈએ; સમીક્ષકો ફક્ત જોઈ અને ટિપ્પણી કરી શકે.",
  'lessons.state.notFound': "આ કોર્સમાં એવો પાઠ નથી.",
  'lessons.state.error': "રૂપરેખા લોડ થઈ નહીં. આ ડિવાઇસ પર કંઈ કૅશ નથી; ફરી પ્રયાસ કરો.",
  'lessons.state.videoRestricted': "વિડિયો સંપાદન પ્રતિબંધિત — અપલોડ માટે આ કોર્સ પર પ્રશિક્ષક ભૂમિકા જોઈએ; સમીક્ષકો ફક્ત જોઈ અને ટિપ્પણી કરી શકે.",
  'lessons.state.quizRestricted': "ક્વિઝ સંપાદન પ્રતિબંધિત — સમીક્ષકો ક્વિઝને શીખનારની જેમ જોઈ શકે, પ્રશ્નો બદલી નહીં શકે.",
