  'lessons.quote': "“ભેંસ બફરિંગની રાહ નથી જોતી — પહેલાં ઑડિયો”",
  'lessons.media.heading': "ફાઇલ",
  'lessons.media.limits': "MP4 અથવા MOV, ઑડિયો માટે MP3/M4A/OGG, દસ્તાવેજ માટે PDF — પ્લેટફોર્મની અપલોડ મર્યાદા સુધી. સ્પષ્ટ કહ્યું છે જેથી ધીમા FPO ઑફિસ લિંક પર અપલોડ ચૂપચાપ નિષ્ફળ ન જાય.",
  'lessons.media.honest': "આ પ્લેટફોર્મ ફાઇલ સાથે શું કરે છે: સંગ્રહે છે, સ્કૅન કરે છે, અને સ્કૅન સ્વચ્છ હોય ત્યારે સર્વ કરે છે. તે ટ્રાન્સકોડ કરતું નથી, ઑડિયો કાઢતું નથી, થંબનેલ ફ્રેમ કાપતું નથી કે સબટાઇટલ ડ્રાફ્ટ કરતું નથી — અહીં “પ્રોસેસિંગ” સ્કૅન છે, અને “તૈયાર” તમારું ચિહ્ન.",
  'lessons.media.none': "હજી કોઈ ફાઇલ જોડાયેલ નથી. ડ્રાફ્ટ સાચવો — સંપાદિત કરો દ્વારા જોડો.",
  'lessons.media.awaiting_scan': "અપલોડ થયું — સ્કૅનની રાહ",
