  'form.lesson.refusal.MEDIA_REQUIRED': "વિડિયો, pdf કે ઑડિયો પાઠને ફાઇલ જોઈએ. અપલોડ કરો કે id પેસ્ટ કરો.",
  'form.lesson.refusal.MEDIA_UNKNOWN': "આ ટેનન્ટના બકેટમાં એવી ફાઇલ નથી (બીજા ટેનન્ટની ફાઇલ, કે ટાઇપો, ફાઇલ નથી).",
  'form.lesson.refusal.MEDIA_KIND_MISMATCH': "ફાઇલનો પ્રકાર પાઠ સાથે મેળ નથી: વિડિયો પાઠ વિડિયો ફાઇલ લે, ઑડિયો ઑડિયો ફાઇલ, pdf એક PDF, લાઇવ વિડિયો કે ઑડિયો રેકોર્ડિંગ.",
  'form.lesson.refusal.MEDIA_NOT_FOR_KIND': "લેખ કે ક્વિઝમાં ફાઇલ હોતી નથી.",
  'form.lesson.refusal.BODY_REQUIRED': "લેખને લખાણ જોઈએ.",
  'form.lesson.refusal.DURATION_REQUIRED': "વિડિયો કે ઑડિયો પાઠને અવધિ (mm:ss) જોઈએ.",
  'form.lesson.refusal.DURATION_INVALID': "ઘડિયાળ નથી: mm:ss, h:mm:ss કે સાદી સેકન્ડ (એક દિવસ સુધી) વાપરો.",
  'form.lesson.refusal.SIBLING_NOT_FOR_KIND': "ફક્ત વિડિયો પાઠ ફક્ત-ઑડિયો જોડિયું નામિત કરે.",
  'form.lesson.refusal.SIBLING_UNKNOWN': "જોડવા માટે આ કોર્સમાં એવો પાઠ નથી.",
  'form.lesson.refusal.SIBLING_NOT_AUDIO': "જોડિયું ફક્ત-ઑડિયો પાઠ હોવું જોઈએ.",
  'form.lesson.refusal.SIBLING_TAKEN': "એ ઑડિયો પાઠ પહેલેથી બીજા વિડિયોનું જોડિયું છે. એક જોડિયું એક વિડિયો માટે.",
  'form.lesson.refusal.SIBLING_IS_SELF': "પાઠ પોતાનું જ જોડિયું ન હોઈ શકે.",
  'form.lesson.refusal.THUMBNAIL_NOT_FOR_KIND': "ફક્ત વિડિયો પાઠ થંબનેલ ફ્રેમ જાહેર કરે.",
