  'form.lesson.refusal.THUMBNAIL_BEYOND_DURATION': "ફ્રેમ પાઠની અવધિની અંદર હોવી જોઈએ.",
  'form.lesson.refusal.CHAPTERS_NOT_FOR_KIND': "ચૅપ્ટર સમય ચિહ્નિત કરે; ફક્ત વિડિયો, ઑડિયો કે લાઇવ પાઠમાં હોય.",
  'form.lesson.refusal.CHAPTER_LINE_INVALID': "ચૅપ્ટર લાઇન `mm:ss શીર્ષક` છે; એક લાઇન વાંચી ન શકાઈ (અથવા 60 થી વધુ છે).",
