  'live.refused.viewers': "કોઈ લાઇવ હાજરી કાઉન્ટર નથી: અહીં કશું સ્ટ્રીમ થતું નથી, તેથી કોઈ દર્શકો ગણતું નથી. હાજરી એ સંખ્યા છે જે તમે વર્ગ પછી નોંધો છો.",
  'live.refused.questions': "કોઈ પ્રશ્ન કતાર અને કોઈ વૉઇસ ટ્રાન્સક્રિપ્ટ નથી: આ પ્લેટફોર્મ પર ચેટ કે વાણી-થી-લખાણ પ્રદાતા નથી.",
  'live.refused.slowMode': "કોઈ સ્લો મોડ નથી: ધીમું કરવા કોઈ ચેટ નથી.",
