  'common.apply': "લાગુ કરો",
  'studio.lead': "તમારું શિક્ષણ, એક જગ્યાએ — જે કોર્સ તમે બનાવો છો, જે શીખનારાઓ સુધી પહોંચો છો, જે વર્ગો તમે ચલાવો છો.",
  'studio.state.noProfile': "તમે અહીં કોર્સ બનાવી શકો છો, પણ આ સહકારીમાં તમારી પ્રશિક્ષક પ્રોફાઇલ હજી નથી. પહેલાં તે બનાવો — પરિચય અને જે ભાષાઓમાં તમે શીખવો છો; પછી એક પ્રમાણપત્ર દાખલ કરો જેથી કન્ટેન્ટ ડેસ્ક તમને ચકાસી શકે.",
  'studio.state.restricted': "સ્ટુડિયોની પરવાનગી જરૂરી — આ સહકારીમાં તમારી ભૂમિકાઓમાં કોર્સ બનાવવાનું નથી. તમારા ટેનન્ટ એડમિનને કહો.",
  'studio.state.notEnabled': "બંધ છે — આ સહકારી કે પ્લાન માટે શિક્ષણ મોડ્યુલ બંધ છે. કંઈ તૂટ્યું નથી; તે ચાલુ નથી.",
  'studio.state.error': "તમારો સ્ટુડિયો લોડ થઈ શક્યો નહીં. અહીં કંઈ કેશ નથી: જૂના આંકડા ચાલુ કહીને બતાવાતા નથી.",
