  'studio.refused.watchMonth': "“આ મહિને”નો આંકડો માપાતો નથી: જોવાનો સમય દરેક પાઠ માટે તારીખ વગરના ચાલુ સરવાળા તરીકે રાખવામાં આવે છે.",
  'studio.refused.rating': "આ પ્લેટફોર્મ પર કંઈ પણ પ્રશિક્ષકનું શીખનારાઓ દ્વારા રેટિંગ નોંધતું નથી; બનાવેલો આંકડો બતાવવાને બદલે કોઈ આંકડો બતાવાતો નથી.",
  'studio.refused.faceMatch': "પ્રમાણપત્ર પર “ચકાસાયેલ”નો અર્થ છે કે કન્ટેન્ટ ડેસ્ક પર કોઈ વ્યક્તિએ દસ્તાવેજ તપાસ્યો. અહીં કંઈ પણ ચહેરો મેળવતું નથી કે પ્રમાણપત્ર વાંચતું નથી.",
  'studio.refused.retry': "ફરી પ્રયાસ કરવા માટે કોઈ સ્વયંસંચાલિત તપાસ નથી: પ્રમાણપત્ર કન્ટેન્ટ ડેસ્ક પર એક વ્યક્તિ જુએ છે.",
  'studio.refused.learnerInsights': "લર્નર ઇનસાઇટ્સ (કોર્સ દીઠ વિશ્લેષણ) આ સ્ટુડિયોનો ભાગ નથી; ઉપરના શીખનારા અને પૂર્ણતા કૉલમ જ આ પ્લેટફોર્મની ગણતરીઓ છે.",
