  'studio.refused.deactivate': "પ્રશિક્ષક પ્રોફાઇલ નિષ્ક્રિય કરવાનું કોઈ કાર્ય નથી; તેના બદલે તમારા કોર્સ આર્કાઇવ કરો અને પ્રોફાઇલ ખાનગી કરો.",
