  'nav.earnings': "કમાણી",
  'studio.tile.earnings.link': "તમારી કમાણી ખોલો — દરેક આંકડો રોયલ્ટી ચોપડામાંથી, ચલણ પ્રમાણે ઉમેરેલો.",
  'earnings.title': "કમાણી",
  'earnings.lead': "રોયલ્ટી દશાંશ સાથેનું સન્માન છે — અહીંનો દરેક આંકડો રોયલ્ટી ચોપડા પરનો સરવાળો છે, દરેક સવેતન નોંધણીની એક લીટી, અભ્યાસક્રમના પોતાના ચલણમાં. કશું અંદાજિત કે કૅશ નથી: જે દેખાય છે તે ચોપડો હાલ રાખે છે.",
