  'earnings.deskViewing': "તમે નાણાં ડેસ્ક તરીકે {name}ની કમાણી વાંચી રહ્યા છો.",
  'earnings.share': "નોંધાયેલો તમારો રોયલ્ટી હિસ્સો: {share}%.",
  'earnings.state.ready': "તૈયાર.",
  'earnings.state.empty': "હજી કોઈ કમાણી નથી.",
  'earnings.state.emptyHint': "તમે શીખવેલા અભ્યાસક્રમોની રોયલ્ટી પહેલી સવેતન નોંધણીથી અહીં દેખાશે. મફત અભ્યાસક્રમો શીખનારા નોંધે છે, પૈસા નહીં.",
  'earnings.state.noProfile': "સ્ટુડિયો ઍક્સેસ જરૂરી — તમારી હજી કોઈ પ્રશિક્ષક પ્રોફાઇલ નથી. પહેલાં એક બનાવો; કમાણી પ્રશિક્ષક રેકોર્ડની હોય છે.",
  'earnings.state.restricted': "કમાણી ફક્ત પ્રશિક્ષક અને નાણાં ડેસ્ક માટે છે. આ રકમો ફક્ત પ્રશિક્ષક અને ટેનન્ટ નાણાં ડેસ્ક જોઈ શકે છે.",
  'earnings.state.notEnabled': "ફ્લેગ બંધ — કમાણી અક્ષમ. આ મોડ્યુલ આ ટેનન્ટ કે પ્લાન માટે બંધ છે. કશું તૂટ્યું નથી અને કશું ખોવાયું નથી: ચોપડો દરેક લીટી રાખે છે; પાનું ફક્ત સક્ષમ નથી.",
  'earnings.state.notEnabledHint': "સ્વિચ instructor_earnings છે, પ્લાન કે ફીચર સેટિંગમાં.",
  'earnings.state.error': "કમાણી લોડ ન થઈ. કશું કૅશ નથી — ફરી પ્રયાસ કરો અને ચોપડો નવેસરથી ઉમેરાશે.",
  'earnings.agreement.title': "રોયલ્ટી કરાર",
  'earnings.agreement.current': "કરાર v{version} {when}એ સ્વીકૃત — તમારો હિસ્સો {share}%.",
  'earnings.agreement.none': "હજી કોઈ રોયલ્ટી કરાર નોંધાયો નથી. તમે એક સ્વીકારો ત્યાં સુધી દરેક ખરીદીનો તમારો હિસ્સો તમારા વૉલેટના હોલ્ડ ખાતામાં રખાય છે — નોંધાયેલો, ખોવાયેલો નહીં — અને સ્વીકારતાં જ મુક્ત થાય છે.",
