  'earnings.agreement.willRelease': "સ્વીકારતાં દરેક રોકેલી લીટી હમણાં તમારા મુખ્ય વૉલેટમાં મુક્ત થશે:",
  'earnings.agreement.note.accept': "તમે પોતે સ્વીકારો છો — કોઈ તમારા માટે સ્વીકારી શકતું નથી, અને ડેટાબેઝ બીજી કોઈ સહી નકારે છે. તમારી રોકેલી રોયલ્ટી એ જ વ્યવહારમાં તમારા મુખ્ય વૉલેટમાં જાય છે.",
