  'templates.editor.fallsBackHere': 'તમારો ફેરફાર ક્યારેય પણ હટાવો — મોકલવાનું અહીં જ પાછું આવે છે, ક્યારેય ચૂપકીદી પર નહીં.',
  'templates.editor.noPlatform': 'આ ઇવેન્ટ × ચેનલ × ભાષાનો કોઈ પ્લેટફોર્મ ડિફોલ્ટ નથી: તમારા ફેરફાર વિના આ ચેનલ "કોઈ ટેમ્પલેટ નથી" નોંધે છે.',
  'templates.editor.variables': 'વેરિએબલ (ઇવેન્ટ દ્વારા નક્કી)',
  'templates.editor.variablesUndeclared': 'આ ઇવેન્ટ માટે હજી કોઈ વેરિએબલ જાહેર નથી, તેથી તમે વાપરો તે કોઈ ચકાસી શકતું નથી. એ અજ્ઞાત છે, શૂન્ય નહીં.',
