  'templates.editor.history': 'આવૃત્તિ ઇતિહાસ',
  'templates.editor.noHistory': 'હજી કોઈ આવૃત્તિ નથી. પહેલી લખાયા પછી તમારા ફેરફારની જૂની આવૃત્તિઓ અહીં દેખાશે.',
  'templates.editor.guardRails': 'સુરક્ષા નિયમો',
  'templates.guard.variables': 'છૂટેલું જરૂરી વેરિએબલ, અથવા જે ઇવેન્ટ જાહેર ન કરે, નામ સાથે સાચવવાનું રોકે છે — સભ્યને ક્યારેય ત્યાં ખાલી જગ્યા મળતી નથી જ્યાં રકમ હોવી જોઈએ.',
  'templates.guard.segments': 'SMS ભાગની ગણતરી ભરેલા લખાણની થાય છે, અને 2 થી વધુ ભાગ સાચવવાનું રોકે છે (ખર્ચ અને ડિલિવરી).',
  'templates.guard.previousKeepsSending': 'ફેરફાર ચાલુ આવૃત્તિની બાજુમાં નવો ડ્રાફ્ટ છે; બીજી વ્યક્તિ મંજૂર કરે ત્યાં સુધી અગાઉના શબ્દો મોકલાતા રહે છે.',
  'templates.editor.recorded': 'દરેક આવૃત્તિ અને દરેક નિર્ણય નોંધાય છે, કોણે અને શા માટે સાથે · દરેક ઇવેન્ટ × ચેનલ × ભાષાનો એક ફેરફાર.',
