  'experiments.refusedWhy': 'પ્રયોગ માટે એ નોંધ જોઈએ કે કયા સભ્યે કયા શબ્દો જોયા, દરેકને કેટલાએ જોયા, અને પછી શું કર્યું. આ પ્લેટફોર્મ પર તેમાંથી કંઈ ક્યાંય નોંધાતું નથી, તેથી આ પેજ કોઈ ભાગ, ટકાવારી કે વિજેતા બતાવતું નથી.',
