  'notif.refused.collapse': 'બન્યું નથી: અપડેટની હારમાળાને એક લાઇનમાં સંકેલવી ("હારમાળા છુપાવો"). ડિલિવરી લૉગ પર કોઈ સંકેલવાની ચાવી નથી, તેથી દરેક અપડેટ પોતાની લાઇન છે.',
