  'notif.refused.masterSwitch': 'બન્યું નથી: ચેનલ મુખ્ય સ્વિચ. આખી ચેનલ માટે સભ્ય કે સંસ્થાનો કોઈ સ્વિચ નથી; ચેનલો ઉપરના કોષ્ટકમાં દરેક ઇવેન્ટ માટે પસંદ થાય છે.',
  'notif.refused.suspendTonight': 'બન્યું નથી: એક રાત માટે શાંત કલાકો રોકવા. તેને બદલે સમય બદલો; તે આગલી સૂચનાથી લાગુ થશે.',
  'notif.refused.centerDisabled': 'બન્યું નથી: સૂચના કેન્દ્ર છુપાવતો સંસ્થા સ્વિચ. કેન્દ્ર અને ઘંટડી ત્યારે જ છુપાય છે જ્યારે સૂચના મોડ્યુલ જ બંધ હોય.',
  'notif.refused.autoRetry': 'બન્યું નથી: આપમેળે ફરી પ્રયાસ. નિષ્ફળ ચેનલ કારણ સાથે નિષ્ફળ રહે છે; કોઈ તેને ફરી મોકલતું નથી (ફરી પ્રયાસ એ જ લાઇન વાપરત, તેથી પ્રયાસ નોંધવાની જગ્યા નથી).',
  'notif.refused.smsCostRupees': 'બતાવ્યું નથી: રૂપિયામાં SMS ખર્ચ. લૉગ દરેક મોકલવા પર ખર્ચ નોંધે છે પણ ચલણ નહીં, તેથી ₹ કુલ અનુમાન હશે.',
  'notif.refused.approvalRoleLock': 'બન્યું નથી: મંજૂરી ભૂમિકાને કારણે પૈસા અને વિવાદ સૂચનાઓ લૉક કરવી. લૉક દરેક ઇવેન્ટ પર છે — લૉક ઇવેન્ટ કોઈ બંધ કરી શકતું નથી.',
  'notif.refused.teamReachability': 'બન્યું નથી: ટીમ એડમિન દ્વારા સભ્યોની ગંભીર પહોંચ જોવી. બીજા સભ્યની પસંદગીઓ જોવાનો કોઈ સ્ટાફ રસ્તો નથી.',
  'notif.refused.retryPageLoad': 'ફરી પ્રયાસ એ પાનું લોડ કરવું છે, કોઈ ક્રિયા નહીં: દરેક "લોડ ન થયું" સ્થિતિ પોતાના જ પાના સાથે જોડાયેલી છે.',
  'notif.refused.popoverKeys': 'ઘંટડીની અંદર તીર-કીથી ફરવા સ્ક્રિપ્ટ જોઈએ, જે આ કન્સોલ મોકલતું નથી; Tab, Enter અને Escape કામ કરે છે.',
  'notif.refused.tierChipAct': 'શ્રેણી ચિપ ફિલ્ટર છે, ક્રિયા નહીં: કેન્દ્રમાં શ્રેણી ફિલ્ટર વાપરો.',
  'notif.refused.digestFrequency': 'બન્યું નથી: સારાંશ આવર્તન. કોઈ સારાંશ નથી, અને તમે કેટલી વાર ઇચ્છો તે સાચવવાની કોઈ કૉલમ નથી.',
