  'form.notif.maths.holds': 'તે દરમિયાન પુશ, SMS, WhatsApp અને વૉઇસ કૉલ રોકાય છે અને અંતે મોકલાય છે; એપ-સૂચનાઓ અને ઇમેઇલ ક્યારેય રોકાતાં નથી; ગંભીર સૂચનાઓ તેને માનતી નથી.',
