  'pages.title': 'પેજ',
  'pages.lead': 'સ્થિર પેજ, નીતિઓ અને મદદ લેખો — માર્કડાઉનમાં, આવૃત્તિઓ સાથે: દરેક પ્રકાશન નવી આવૃત્તિ બનાવે છે અને જૂની બધી ઇતિહાસમાં રહે છે. પ્લેટફોર્મના ડિફોલ્ટ જરૂરી બાબતો સંભાળે છે; તમારું પોતાનું પ્રકાશિત પેજ તમારા સભ્યો માટે પ્લેટફોર્મવાળાની જગ્યા લે છે.',
