  'bc.title': "જાહેરાતો",
  'bc.lead': "જાહેરાત તમારા સક્રિય સભ્યોને જાય છે — બધાને, અથવા એક ભૂમિકા ધરાવતા સભ્યોને — ઍપમાં સંદેશ તરીકે, અને જ્યાં સભ્યનું ઉપકરણ છે ત્યાં પુશ તરીકે. નીચેનું દરેક પરિણામ ડિલિવરી લૉગમાંથી વાંચેલું છે.",
  'bc.notWhatsApp': "આ વોટ્સએપ નથી. પ્લેટફોર્મ પાસે કોઈ વોટ્સએપ પ્રદાતા, નંબર કે ટેમ્પલેટ નથી, એટલે અહીંથી કંઈ પણ વોટ્સએપ પર જતું નથી — અને કોઈ જાહેરાત ક્યારેય જબરદસ્તી SMS પર મોકલાતી નથી.",
