  'kyc.desk.refused.kycCamp': "“કેમ્પ શનિ 18 જુલાઈ”: બતાવ્યું નથી — પ્લેટફોર્મમાં કેવાયસી કેમ્પનો કોઈ રેકર્ડ નથી.",
  'kyc.desk.refused.categoryPause': "“તે શ્રેણીઓ આપોઆપ અટકે છે”: અહીં સાચું નથી — કોઈ નિયમ દસ્તાવેજ પ્રકારને લિસ્ટિંગ શ્રેણીઓ સાથે જોડતો નથી; સમાપ્ત દસ્તાવેજ ફક્ત તેની ભૂમિકાઓનો નાણાં-દરવાજો બંધ કરે છે.",
  'kyc.desk.refused.maskedPreview': "“પ્રિવ્યૂમાં નંબર છુપાયેલા”: ફાઇલનું કોઈ છુપાવેલું સ્વરૂપ નથી — પુરાવો ક્યારેય સીધો બતાવાતો નથી; તેને ખોલવું એક નોંધાયેલું ખુલાસો છે.",
  'kyc.desk.refused.platformDesk': "“પ્લેટફોર્મ ચકાસણી દ્વારા ચકાસાયેલ”: પ્લેટફોર્મ ડેસ્ક હજુ બન્યું નથી; નિર્ણય આ સંસ્થાનું ચકાસણી ડેસ્ક (kyc.review) કરે છે — જમા કરનાર ક્યારેય નહીં, જેનો દસ્તાવેજ તે ક્યારેય નહીં, અને સંસ્થાનો દસ્તાવેજ તેનો પોતાનો વહીવટકર્તા ક્યારેય નહીં.",
  'kyc.desk.refused.orgPayoutLink': "“બંને ચકાસાય ત્યારે ચુકવણી ખૂલે”: જોડાયું નથી — સભ્ય ચુકવણી સભ્યની પોતાની ભૂમિકા-કેવાયસી પર અટકે છે; સંસ્થાની ચકાસણી અહીં અને ગો-લાઇવ યાદીમાં દેખાય છે.",
