  // ---- PC-56 TENANT-9c · THE AUDITOR REALM (W200 · W201 · W436 · W437 · W2498–W2502) ----
  'auditor.title': "ઑડિટર કન્સોલ",
  'auditor.lead': "તમારા CA અને વૈધાનિક ઑડિટર માટે: ખાતાવહી જેવી છે, ઑડિટ ટ્રેલ જેમ બન્યું, અને કન્ટેન્ટ-હૅશવાળા એક્સપોર્ટ. અહીં દરેક આંકડો આ જ વાંચન પર ગણાયો છે.",
  'auditor.banner.title': "ફક્ત-વાંચન ક્ષેત્ર — લાગુ, છુપાવેલું નહીં",
  'auditor.banner.body': "જે સત્રમાં ઑડિટર ભૂમિકા છે, તેને આ પ્લેટફોર્મના દરેક રૂટ પર દરેક લેખન એક જ ગાર્ડથી નકારાય છે. એકમાત્ર અપવાદ એક્સપોર્ટ કતારમાં મૂકવાનો છે (અને તેની ફાઇલ લેવી, અને સાઇન-આઉટ): તે એક કતાર-પંક્તિ અને એક રેકોર્ડ લખે છે, કોઈ વ્યાવસાયિક ડેટા બદલતું નથી.",
