  'auditor.reveal.restricted': "ખોલવા માટે member.pii.reveal જોઈએ, અને દરેક ખુલાસો કારણ સાથે નોંધાય છે. ઑડિટર પાસે તે નથી — છુપાવેલા ઓળખકર્તા જ ઑડિટરનું દૃશ્ય છે.",
