  'auditor.ledger.title': "ખાતાવહી વિગત",
  'auditor.ledger.banner': "ફક્ત-વાંચન — અને આ દૃશ્ય નોંધાયેલું છે. નીચે દરેક પક્ષ આ સહકારી સાથે બંધાયેલા એક જ માર્ગથી ખાતાવહીમાંથી લેવાયો છે: તેના પોતાના ખાતાંના પક્ષ બાકી અને હૅશ કડી બતાવે છે; વહેંચાયેલા પ્લેટફોર્મ ખાતાંના પક્ષ ફક્ત રકમ, અને તેમની કડી નામથી રોકી છે.",
