  "amb.refused.reassignment": "કોઈ પુનઃસોંપણી નોંધાતી નથી: 60 દિવસ નિષ્ક્રિય રહેવાથી પણ આ પ્લેટફોર્મ પર ક્લસ્ટર બદલાતું નથી.",
